pub use semio_framework_value_retained_clone as retained_clone;
pub mod __private{pub use semio_framework_value_snapshot_projection::snapshot_projection;}
use semio_framework_value_derive::{RetireOwned,SnapshotProjection};
use semio_framework_value_snapshot_projection::SnapshotProjection as Projection;
#[derive(RetireOwned,SnapshotProjection)]
#[value(crate="crate",boxed_original)]
struct Nested{count:u64}
#[derive(RetireOwned,SnapshotProjection)]
