#[test]fn record_seed_has_no_candidate_allocation(){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();assert!(!law["value"].as_str().unwrap().is_empty());let(cursor,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Record as Projection>::projection_seed());assert_eq!(heap,(0,0));drop(cursor)}

