#[derive(Clone,Copy,PartialEq,Eq)]enum RecordOp{Advance,Take,Start,Close,Output}
struct RecordContext<'a>{source:RetainedCloneRef<'a,Record>,turn:OriginalSourceTurnIdentity,op:RecordOp}
struct RecordProducer{cursor:ManuallyDrop<RecordSnapshotProjection>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity,route:Option<(OriginalEffectInvocationIdentity,RecordOp)>,output:ManuallyDrop<Option<Box<Record>>>,output_close:ManuallyDrop<RetainedCloneClose>,calls:usize,recoveries:usize,panic_at:Option<usize>}
impl RecordProducer{
 fn terminal(&self)->bool{self.route.is_none()&&self.cursor.terminal_is_empty()&&self.output.is_none()&&self.output_close.is_empty()}
 fn dispatch<'r>(&mut self,c:&mut RecordContext<'_>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let inv=effect.invocation().ok_or_else(||ValueError::invariant("record law invocation absent"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if inv.mode()!=mode{return Err(ValueError::invariant("record law mode changed"))}let key=(inv.identity(),c.op);if recover{if self.route!=Some(key){return Err(ValueError::invariant("record law route changed"))}}else if self.route.is_some(){return Err(ValueError::invariant("record law route occupied"))}let mut scope=reply.scope(&mut self.route,key)?;let done=match(c.op,recover){(RecordOp::Advance,false)=>self.cursor.advance_into(c.source,4096,4096,effect,scope.borrow()?)?,(RecordOp::Advance,true)=>self.cursor.recover_advance_into(c.source,4096,4096,effect,scope.borrow()?)?,(RecordOp::Take,false)=>{let mut inner=None;drop(self.cursor.take_into(&mut self.output,effect,OriginalEffectReply::borrow(&mut inner)?)?);scope.borrow()?.complete(inner.ok_or_else(||ValueError::invariant("record output reply absent"))?.map_err(Into::into))},(RecordOp::Take,true)=>return Err(ValueError::invariant("native output cannot recover without recorded reply")),(RecordOp::Output,false)=>{if self.output_close.is_empty(){let turn=self.output_close.begin_granted(&mut self.output,effect);scope.borrow()?.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into))}else{self.output_close.step_into(4096,effect,scope.borrow()?)?}},(RecordOp::Output,true)=>self.output_close.recover_step_into(4096,effect,scope.borrow()?)?,(RecordOp::Start,false)=>self.cursor.begin_close_into(effect,scope.borrow()?)?,(RecordOp::Start,true)=>self.cursor.recover_begin_close_into(effect,scope.borrow()?)?,(RecordOp::Close,false)=>self.cursor.close_into(4096,effect,scope.borrow()?)?,(RecordOp::Close,true)=>self.cursor.recover_close_into(4096,effect,scope.borrow()?)?};drop(done);self.calls+=1;if self.panic_at==Some(self.calls){self.panic_at=None;panic!("recorded record child reply interruption")}Ok(scope.forwarded())}
}
impl Drop for RecordProducer{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.terminal());unsafe{ManuallyDrop::drop(&mut self.cursor);ManuallyDrop::drop(&mut self.output);ManuallyDrop::drop(&mut self.output_close)}}}
impl OriginalEffectProducer for RecordProducer{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=RecordContext<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("record law Source changed"))}Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,false)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.recoveries+=1;self.dispatch(c,e,r,true)}
}
fn record_grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run_record_cancel(cut:Option<usize>,publish:bool,interrupt:bool){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();let mut source=RetainedCloneSource::<Record>::from_owner(Record{value:law["value"].as_str().unwrap().to_owned(),nested:Nested{count:law["original"].as_u64().unwrap()}});let id=source.borrow().reference_identity();let pointer=source.borrow().get().value.as_ptr();let mut authority=None;source.with_bank(|_,bank|{let(poll,_)=bank.run_with_source(RetainedCloneGrant::default(),0,|_,witness|{authority=Some(OriginalEffectAuthority::new(RecordProducer{cursor:ManuallyDrop::new(<Record as Projection>::projection_seed()),source:id,turn:witness.identity(),route:None,output:ManuallyDrop::new(None),output_close:ManuallyDrop::new(Default::default()),calls:0,recoveries:0,panic_at:if interrupt{Some(law["unwindAt"].as_u64().unwrap() as usize)}else{None}}));RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(poll,RetainedWorkPoll::Complete(_)))}).unwrap();let mut action=None;let mut answer=None;if cut==Some(1){source.with_bank(|original,bank|{let before=bank.wallet().remaining_work();let(poll,actual)=bank.run_with_source(RetainedCloneGrant::default(),1,|effect,witness|{let start=effect.performed_work();let mut context=RecordContext{source:original,turn:witness.identity(),op:RecordOp::Advance};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-start;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}});assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(actual,None);assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.take().unwrap().unwrap();assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(bank.take_admitted(),None);assert_eq!(bank.wallet().remaining_work(),before)}).unwrap()}let mut op=RecordOp::Advance;let mut ready=false;let mut advances=0;let mut interruptions=0;for _ in 0..4096{let p=authority.as_ref().unwrap();if op==RecordOp::Advance&&p.inspect(|p|p.cursor.ready()){ready=true;op=if publish{RecordOp::Take}else{RecordOp::Start}}if op==RecordOp::Close&&p.inspect(|p|p.cursor.terminal_is_empty()){if publish{op=RecordOp::Output}else{break}}if op==RecordOp::Output&&p.inspect(RecordProducer::terminal){break}let(d,work)=source.with_bank(|original,_|p.inspect(|p|match op{RecordOp::Advance=>(p.cursor.demands(original,4096,4096).unwrap(),p.cursor.advance_work_demand(original,4096,4096).unwrap()),RecordOp::Take=>(p.cursor.take_demand().unwrap(),p.cursor.take_work_demand().unwrap()),RecordOp::Output=>{assert!(!p.output_close.requires_original_birth());assert!(!p.output_close.requires_original_control());(p.output_close.next_owner_demands::<Box<Record>>(p.output.is_some(),&None,4096).unwrap(),p.output_close.next_owner_work::<Box<Record>>(p.output.is_some(),&None,4096).unwrap())},RecordOp::Start=>(p.cursor.begin_close_demand().unwrap(),p.cursor.begin_close_work_demand().unwrap()),RecordOp::Close=>{assert!(!p.cursor.requires_original_birth());assert!(!p.cursor.requires_original_control());(p.cursor.close_demands(4096).unwrap(),p.cursor.close_work_demand(4096).unwrap())}})).unwrap();let grant=record_grant(d);let mut interrupted=0;let((poll,actual),heap)=loop{let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||source.with_bank(|original,bank|{let observed=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(grant,work,|effect,witness|{let before=effect.performed_work();let mut context=RecordContext{source:original,turn:witness.identity(),op};let done=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if done{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));if let(RetainedWorkPoll::Complete(_),_)=&observed.0{assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.as_ref().unwrap().as_ref().unwrap();assert_eq!(observed.1,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,observed.1)}observed}).unwrap()));match attempt{Ok(value)=>break value,Err(_)=>{interrupted+=1;interruptions+=1;assert!(interrupt&&interrupted==1&&interruptions==1)}}};if interrupted>0{assert_eq!(interrupted,1)}assert!(matches!(poll,RetainedWorkPoll::Complete(_)));if let Some(actual)=actual{assert_eq!(actual,heap.0)}answer.take().unwrap().unwrap();assert_eq!(source.borrow().get().value.as_ptr(),pointer);if op==RecordOp::Advance{advances+=1;if cut==Some(1)&&advances==1{let mut foreign=RetainedCloneSource::<Record>::from_owner(Record{value:law["value"].as_str().unwrap().to_owned(),nested:Nested{count:law["original"].as_u64().unwrap()}});assert!(authority.as_ref().unwrap().inspect(|p|p.cursor.demands(foreign.borrow(),4096,4096).is_err()));for _ in 0..10000{if foreign.terminal_is_empty(){break}match foreign.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("foreign Source close refused"),_=>{}}}assert!(foreign.terminal_is_empty())}if cut==Some(advances){op=RecordOp::Start}}else if op==RecordOp::Take{assert!(authority.as_ref().unwrap().inspect(|p|p.output.as_ref().unwrap().value==law["value"].as_str().unwrap()&&p.output.as_ref().unwrap().nested.count==law["original"].as_u64().unwrap()));op=RecordOp::Start}else if op==RecordOp::Start{op=RecordOp::Close}}assert_eq!(interruptions,usize::from(interrupt));if interrupt{assert_eq!(authority.as_ref().unwrap().inspect(|p|p.recoveries),0)}if cut.is_none(){assert!(ready)}else{assert_eq!(Some(advances),cut)}assert!(authority.as_ref().unwrap().inspect(RecordProducer::terminal));
 source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<RecordProducer>::producer_transfer_demand().unwrap();let grant=record_grant(d);let mut producer=None;let((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run_with_source(grant,1,|effect,witness|{let c=RecordContext{source:original,turn:witness.identity(),op:RecordOp::Close};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&c,&mut producer,effect))}));let RetainedWorkPoll::Complete(done)=poll else{panic!("record producer transfer pending")};let progress=done.result.unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);let witness=unsafe{RetainedCursorRelease::native(RecordProducer::terminal)};let grant=record_grant(witness.inline_demand());let mut reply=None;let((poll,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,1,|effect|{let before=effect.performed_work();drop(witness.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let step=reply.take().unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap)}).unwrap();for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("record source close refused"),_=>{}}}assert!(source.terminal_is_empty());}

#[test]fn generated_record_cancels_resident_field_on_original_source(){run_record_cancel(None,false,false)}
#[test]fn generated_record_cancels_each_early_native_phase(){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();for cut in law["cuts"].as_array().unwrap(){run_record_cancel(Some(cut.as_u64().unwrap() as usize),false,false)}}

#[test]fn generated_record_publishes_and_retires_actual_box(){run_record_cancel(None,true,false)}

#[test]fn boxed_scalar_original_closes_with_its_source_bank(){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();let value=law["value"].as_str().unwrap().len() as u64;let mut source=RetainedCloneSource::<Box<u64>>::from_owner(Box::new(value));assert_eq!(**source.borrow().get(),value);let pointer=source.borrow().get().as_ref() as *const u64;assert!(matches!(source.close_with(4096,RetainedCloneGrant::default()).unwrap(),FixtureCloseStep::Denied));assert_eq!(source.borrow().get().as_ref() as *const u64,pointer);for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("boxed scalar source close refused"),_=>{}}}assert!(source.terminal_is_empty());}

