#[derive(RetireOwned,SnapshotProjection)]
#[value(crate="crate",boxed_original)]
struct LargeRecord{items:[u8;8192]}
#[test]fn generated_large_record_birth_fits_one_bounded_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();assert_eq!(law["largeLength"].as_u64().unwrap(),8192);let demand=<LargeRecord as Projection>::projection_birth_demand();assert!(demand.copy_bytes<=law["maximumCopy"].as_u64().unwrap() as usize,"large record cursor birth requires {} copied bytes and its active field owner occupies {} bytes",demand.copy_bytes,std::mem::size_of::<semio_framework_value_snapshot_projection::snapshot_projection::CapturedProjectionField<LargeRecord,[u8;8192]>>());}

#[test]fn generated_large_array_field_seed_fits_one_bounded_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();let bytes=std::mem::size_of::<semio_framework_value_snapshot_projection::snapshot_projection::CapturedProjectionField<LargeRecord,[u8;8192]>>();assert!(bytes<=law["maximumCopy"].as_u64().unwrap() as usize,"large active field seed needs {bytes} bytes, array actor {}, field cursor {}, projection alias {}, close {}",std::mem::size_of::<semio_framework_value_snapshot_projection::snapshot_projection::ArrayProjection<u8,8192>>(),std::mem::size_of::<retained_clone::RetainedFieldCursor<u8>>(),std::mem::size_of::<retained_clone::RetainedOwnedProjectionAdmission<u8>>(),std::mem::size_of::<retained_clone::RetainedCloneClose>());}


fn run_native_large_array_placement(cancel:bool){let law:serde_json::Value=serde_json::from_str(include_str!("record.json")).unwrap();let count=law["placement"]["chunkElements"].as_u64().unwrap() as usize;let mut source=RetainedCloneSource::<u64>::from_owner(7);let mut foreign=RetainedCloneSource::<u64>::from_owner(8);let mut input=Some(Box::new([31u8;8192]));let pointer=input.as_ref().unwrap().as_ptr();let mut target=Box::new(std::mem::MaybeUninit::<[u8;8192]>::uninit());let mut actor=None;source.with_bank(|_,bank|{macro_rules! step{($d:expr,$w:expr,$effect:ident,$reply:ident,$body:block)=>{{let grant=record_grant($d);let mut answer=None;let ((poll,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,$w,|$effect|{let before=$effect.performed_work();let $reply=OriginalEffectReply::borrow(&mut answer).unwrap();drop($body.unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:$effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let result=answer.take().unwrap().unwrap();assert_eq!(actual.unwrap_or(0),heap.0);assert_ne!(bank.take_admitted(),Some(false));bank.post(result.progress(),grant,heap);result}}}let d=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::admission_demand();step!(d,1,e,r,{unsafe{semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::admit_into(&mut input,target.as_mut(),&mut actor,RetainedCopy::new(),e,r)}});assert!(input.is_none());assert_eq!(actor.as_ref().unwrap().source_address(),Some(pointer));let demand=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::copy_demand(count).unwrap();let work=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::copy_work(count).unwrap();let mut short=record_grant(demand);short.maximum_copy_bytes-=1;let before=bank.wallet().remaining_work();let mut denied=None;let(poll,marker)=bank.run(short,work,|effect|{drop(actor.as_mut().unwrap().copy_into(count,effect,OriginalEffectReply::borrow(&mut denied).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(marker,None);assert_eq!(denied.take().unwrap().unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actor.as_ref().unwrap().initialized(),0);assert_eq!(bank.wallet().remaining_work(),before);assert_eq!(bank.take_admitted(),None);foreign.with_bank(|_,other|{let grant=record_grant(demand);let(poll,marker)=other.run(grant,work,|effect|{let mut answer=None;let result=actor.as_mut().unwrap().copy_into(count,effect,OriginalEffectReply::borrow(&mut answer).unwrap());assert!(result.is_err());assert!(answer.is_none());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(marker,None);assert_eq!(other.take_admitted(),None);assert_eq!(actor.as_ref().unwrap().initialized(),0)}).unwrap();for expected in law["placement"]["offsets"].as_array().unwrap().iter().skip(1).take(if cancel{1}else{usize::MAX}){let d=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::copy_demand(count).unwrap();let w=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::copy_work(count).unwrap();step!(d,w,e,r,{actor.as_mut().unwrap().copy_into(count,e,r)});assert_eq!(actor.as_ref().unwrap().initialized(),expected.as_u64().unwrap() as usize);assert_eq!(actor.as_ref().unwrap().source_address(),Some(pointer));if actor.as_ref().unwrap().initialized()==law["placement"]["deniedOffset"].as_u64().unwrap() as usize{let before=bank.wallet().remaining_work();let mut denied=None;let(poll,marker)=bank.run(short,work,|effect|{drop(actor.as_mut().unwrap().copy_into(count,effect,OriginalEffectReply::borrow(&mut denied).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(marker,None);assert_eq!(denied.take().unwrap().unwrap().progress(),RetainedCloneProgress::default());assert_eq!(actor.as_ref().unwrap().initialized(),law["placement"]["deniedOffset"].as_u64().unwrap() as usize);assert_eq!(bank.wallet().remaining_work(),before);assert_eq!(bank.take_admitted(),None)}}let d=actor.as_ref().unwrap().release_demand();step!(d,1,e,r,{if cancel{actor.as_mut().unwrap().cancel_source_into(e,r)}else{actor.as_mut().unwrap().release_source_into(e,r)}});let d=semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::<u8,8192>::finish_demand();step!(d,1,e,r,{semio_framework_value_snapshot_projection::NativeArrayFieldPlacement::finish_into(&mut actor,e,r)});assert!(actor.is_none());}).unwrap();if cancel{drop(target)}else{let output=unsafe{target.assume_init()};assert!(output.iter().all(|value|*value==31));}for _ in 0..10000{if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());for _ in 0..10000{if foreign.terminal_is_empty(){break}foreign.close_once().unwrap();}assert!(foreign.terminal_is_empty())}
#[test]fn native_large_array_placement_retains_real_prefix_and_source(){run_native_large_array_placement(false)}
#[test]fn native_large_array_placement_cancels_partial_prefix(){run_native_large_array_placement(true)}

